import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/messages.js';
import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
import type {ExtWebSocket} from './connectionHandler.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {AIError} from '../../types/ai.js';
import type {MessageChunk} from '../../types/ai.js';
import {
  createUserEntry,
  createAssistantEntry,
  createThinkingEntry,
  createToolEntry,
} from '../../orchestration/entryFactories.js';
import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
import {log} from '../../shared/logger.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  suppressOutput: boolean;
  sentAssistantIndices: number[];
}

type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, sessionStore, validation));
  };
}

// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  sessionStore: SessionStore,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    return;
  }
  const startedAt = Date.now();
  try {
    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
  } finally {
    endTurn(ws, session, signal, startedAt);
  }
}

// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  sessionStore: SessionStore,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, sessionStore, validation);
}

// Everything but a turn is answered at once, off the per-session lock: a list mutates nothing and must not queue behind a stream.
async function answerFrame(ws: WebSocket, sessionStore: SessionStore, validation: ValidationResult): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await answerListSessions(ws, sessionStore, message);
}

// The list is always the connection's own: the user id is the upgrade's, read from the socket, never from the frame.
async function answerListSessions(ws: WebSocket, sessionStore: SessionStore, message: ListSessionsMessage): Promise<void> {
  const {userId} = ws as ExtWebSocket;
  try {
    const summaries = await sessionStore.listFor?.(userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: (summaries ?? []).map(summaryFrameOf)});
  } catch (error) {
    // The log carries the store's detail, the frame none of it: a client that cannot list must not read why.
    log.error('ws', 'conversation list failed', {
      userId,
      error: error instanceof Error ? error.message : String(error),
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}

// The two times go over the wire as ISO strings: a Date does not survive JSON.stringify as a Date.
function summaryFrameOf(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
  try {
    await action();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const code = error instanceof AIError ? error.code : 'UNKNOWN';
    log.error('message', 'handling error', {error: message, code});
    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
      return;
    }
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

async function handleUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  content: string,
  signal: AbortSignal | undefined
): Promise<void> {
  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});

  const userEntry = createUserEntry(content);
  const userIndex = appendEntry(session, userEntry);
  sendUpsert(ws, userIndex, userEntry);

  const parser = new ThinkingTagParser();
  const state: StreamState = {
    thinkingIndex: null,
    assistantIndex: null,
    suppressOutput: false,
    sentAssistantIndices: [],
  };

  let textChunkCount = 0;

  try {
    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
      if (signal?.aborted) break;
      textChunkCount = logChunk(chunk, textChunkCount);
      processChunk(ws, session, state, parser, chunk);
    }
  } finally {
    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
    flushHeldText(ws, session, state, parser);
    closeCutOff(ws, session, state, 'thinkingIndex');
    closeCutOff(ws, session, state, 'assistantIndex');
  }

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }
  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
}

// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
function logChunk(chunk: MessageChunk, textChunkCount: number): number {
  if (chunk.type === 'text') return textChunkCount + 1;

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }

  if (chunk.type === 'tool_result') {
    log.debug('stream', 'tool_result chunk', {
      messageCount: chunk.clientMessages.length,
      types: chunk.clientMessages.map(m => m.type),
    });
    return 0;
  }

  log.debug('stream', 'chunk', {type: chunk.type});
  return 0;
}

function processChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  chunk: MessageChunk
): void {
  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
}

function processTextChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  text: string
): void {
  const segments = parser.push(text);
  for (const segment of segments) {
    handleTextSegment(ws, session, state, segment);
  }
}

function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
  if (segment.type === 'thinking') {
    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
    return;
  }
  commitAndClear(ws, session, state, 'thinkingIndex');
  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
}

function streamSegment(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  key: StateIndexKey,
  createEntry: EntryFactory,
  content: string
): void {
  const isNew = initSegment(session, state, key, createEntry);
  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
  appendDelta(session, state[key]!, content);
  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
}

// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
  markSuppressed(session, index);
  sendSkip(ws, index);
}

function markSuppressed(session: ChatSession, index: number): void {
  const entry = session.entries[index];
  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
}

function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
  if (state[key] !== null) return false;
  state[key] = appendEntry(session, createEntry());
  return true;
}

function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;

  commitEntry(session, index);
  state[key] = null;

  // Only what the client received can be retracted, and only assistant entries.
  if (state.suppressOutput) return;

  sendCommit(ws, index);
  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
}

function processToolUseChunk(
  ws: WebSocket,
  session: ChatSession,
  toolCall: {name: string; input: Record<string, unknown>}
): void {
  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
  const toolIndex = appendEntry(session, toolEntry);
  sendUpsert(ws, toolIndex, toolEntry);
}

function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
  for (const msg of clientMessages) {
    log.debug('stream', 'forwarding client message to frontend', {
      type: msg.type,
      index: 'index' in msg ? msg.index : undefined,
    });
    sendJson(ws, msg);
  }
}

// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
  commitOpenEntries(ws, session, state);
  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});

  for (const idx of state.sentAssistantIndices) {
    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
    markSuppressed(session, idx);
  }

  state.sentAssistantIndices = [];
  state.suppressOutput = true;
}

function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  flushHeldText(ws, session, state, parser);
  commitOpenEntries(ws, session, state);
}

// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  for (const segment of parser.flush()) {
    handleTextSegment(ws, session, state, segment);
  }
}

// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;
  markTruncated(session, index);
  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
  commitAndClear(ws, session, state, key);
}

function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
  commitAndClear(ws, session, state, 'thinkingIndex');
  commitAndClear(ws, session, state, 'assistantIndex');
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

content.thinking:
When run in parallel, `failed: []` — the error frame is MISSING and, in test 3, `accepted` missing the session_list, though `logged` DID capture 'database offline'. So the listFor rejection happened (log written) but the error frame wasn't collected by the client before the pong arrived.

Root cause: timing. The client sends `list_sessions` then immediately `ping`. The server answers the error asynchronously (await listFor → rejection goes through microtask + wsErrorHandler) and the pong synchronously. Order on the server: handleMessage(list) starts → wsErrorHandler(async () => answerFrame(...)) → answerFrame → `await answerListSessions(...)` → within it, `sessionStore.listFor?.(...)` returns a rejected promise → the await yields to the microtask queue. Meanwhile the ping frame arrives and its pong is sent synchronously — the pong can be written BEFORE the error frame. The client's `pong` handler resolves the promise and `askAfterConnect` returns; the error frame may not have been delivered to the client yet (or arrives just after). Under parallel CPU contention, the loss window widens.

Wait — but was this a problem before my change? Before, there was no handler at all, so the test failed differently. The pre-existing test design assumed the error frame precedes the pong. On CI (single-threaded-ish? CI runs jest with workers too) — CI's run DID pass?? No — CI's test failure was the missing handler entirely. So this ordering flakiness is new territory introduced by the async error path.

Hmm, actually wait. Let me think about the ordering guarantee more carefully. Server-side, frames are written in this order:
1. list frame arrives → handleMessage → validation ok → wsErrorHandler → answerFrame → answerListSessions → `await sessionStore.listFor(...)` — listFor returns `Promise.reject(...)`; awaiting a rejected promise continues in a microtask... BUT ws.send is synchronous write to the socket buffer. The rejection continuation runs on the microtask queue BEFORE the ping message event? Socket data events are macrotasks. Order: message(list) handler runs sync up to the first await; control returns; message(ping) event → handlePing sends pong synchronously... 

Actually — the 'message' events: both frames may already be buffered; node delivers them as separate 'message' events in order. Event loop: message(list) → handler runs, hits await, returns. message(ping) → sends pong immediately (sync). THEN microtasks drain: the await continuation → catch → log + sendError. So pong is written BEFORE the error frame! 

Wait, no — microtasks drain between macrotasks: after message(list) handler returns, the microtask queue drains BEFORE the next macrotask (message(ping)). The `await` continuation (rejection → catch → sendError) is a microtask scheduled when listFor's rejection settles. `Promise.reject(x)` settles immediately; `await` schedules continuation as microtask. So: message(list) macrotask → handler runs to first await → yields → microtask queue drains → sendError runs → THEN message(ping) macrotask → pong. So the error frame IS written before the pong, in a single-event-loop-turn scenario where both frames are already buffered.

BUT the store's `listFor: () => Promise.reject(...)` — the rejection is immediate, so the continuation is a microtask → sendError before pong. Hmm — so ordering should hold... unless the frames arrive in SEPARATE event-loop turns (TCP packet boundaries), in which case: message(list) → microtask → error frame written ✓ still before ping arrives at all. Even better.

Then why did `failed` end up empty while `logged` had the entry?? The log captured the rejection — so sendError should have run right after. Unless... `ws.send` after `client.terminate()`?? No. Hmm — look: `failed: Array []` but logged has the entry. So the server DID answer, but the client didn't record the frame. The client resolves on pong and stops collecting — if pong arrived BEFORE the error frame, the error frame lands in `frames` maybe not at all (listener still attached, but we've already returned... actually the promise resolved and askAfterConnect returns; the error message event may fire later — not collected).

So pong beat the error frame. How? ... `sendError` inside my catch — before it, `log.error`. `log` is the synchronous array push ✓. Hmm.

OH WAIT. I see it — `wsErrorHandler` in handleMessage wraps `answerFrame`:
```ts
return wsErrorHandler(ws, async () => answerFrame(ws, sessionStore, validation));
```
answerListSessions catches the error internally and does NOT rethrow — so wsErrorHandler isn't involved. Inside answerListSessions: `await sessionStore.listFor?.(...)` → rejection → catch → log + sendError. Microtask ordering as analyzed: should beat pong.

Unless the ping frame's 'message' event fires in the SAME macrotask batch... no, each 'message' is its own macrotask.

Hmm — but wait: node delivers multiple buffered frames: `ws.on('message')` per frame. Actually ws may emit both messages... each emits separately. After the list handler returns (at first await), microtasks drain: `await` on an already-rejected promise schedules ONE microtask... sendError executes → writes to socket. Then pong. Order preserved: client sees error THEN pong. Client's listener: error → frames.push; pong → resolve. Both processed → frames=[error] ✓.

So why flaky under parallel load? Timing again: the client's sends. `askAfterConnect` sends list and ping back-to-back on 'connected'. TCP can coalesce them into one segment; server reads both in one 'data' chunk; ws parses both and emits two 'message' events — still ordered, microtask drain between them.

Hmm, but what about the OTHER direction — the client's receipt: server writes error frame, then pong. Client receives data; ws emits 'message' error → push; 'message' pong → resolve. Fine...

So why did `failed` come out empty while `logged` shows the error? ... Let me reconsider: maybe the error frame WAS sent but AFTER the client resolved. For that, pong must be written first. When could pong be written first? If the ping's 'message' event is processed BEFORE the list rejection microtask drains. That happens if... the list handler's await chain has MORE than one hop! Look: handleMessage → wsErrorHandler(ws, async () => answerFrame(...)) — `wsErrorHandler` does `try { await action(); }` — awaiting an async IIFE: calling the IIFE runs answerFrame synchronously up to its first await (`await answerListSessions(...)`), which runs answerListSessions synchronously up to ITS first await (`await sessionStore.listFor?.(...)`), which... `listFor` is called, returns rejected promise, await schedules continuation microtask m1. Stack unwinds back through wsErrorHandler's `await action()` — scheduling m2 after m1. So m1 (the catch with sendError) runs before m2. Still before pong (next macrotask).

Hmm, so in THEORY the error precedes the pong. But under parallel jest workers, the process gets descheduled; that doesn't reorder microtasks vs macrotasks though...

WAIT. Actually — maybe the issue is completely different: `failingList` engine — TWO engines started (`withoutList` then `failingList`), and `unimplemented` asked on the FIRST engine, `failed` on the second. In the parallel run, `unimplemented` PASSED (its diff showed only `failed` and `accepted` wrong)... 

Hmm, look at the second failure shown: test 3's `accepted: Array []` — accepted = the bare list frame answered with session_list []. `accepted` was empty but `calls: 1`? (the diff truncated). In test 3, `accepted` frames from `askAfterConnect(url, {type: 'list_sessions'})` — the response requires `await sessionStore.listFor(...)` (sync store returning []) — hmm, `listFor: () => { calls += 1; return []; }` returns a plain array (not a promise) — `await` on a non-promise still defers to a microtask. Same ordering logic.

So both failures are the same phenomenon: the pong resolves the client before the session_list/error frame arrives. The pong is sent... hmm wait, actually, is the pong really sent after? Let me re-examine: `handlePing` uses `ws.send` directly. And answerListSessions' sendJson also `ws.send`. Order of ws.send calls: error/list frame must be first.

OK let me think about WHEN pong could beat it: **if the list frame's handleMessage is NOT the first thing processed** — the connectionHandler `ws.on('message')` calls `deps.handleMessage(ws, session, parsed, connection.signal)` — note: handleMessage is `async`? `return function handleMessage(...): Promise<void>` — it's a regular function returning a promise. Called synchronously up to first await... Actually is `handleMessage` itself async? `return function handleMessage(ws, session, rawMessage, signal?): Promise<void> { ... }` — NOT async, but it returns `lock.run(...)` or `wsErrorHandler(...)` promise. Inside, `validateMessage` runs sync. So up to the first real await, everything runs synchronously within the message event.

Hmm OK — so where does the ping get answered? ping goes: `wsErrorHandler(ws, async () => answerFrame(...))` — answerFrame: `if ping → handlePing(ws, ts)` — handlePing sends pong SYNCHRONOUSLY inside the promise executor before wsErrorHandler's await. So pong is written in the same macrotask as the ping event.

Now the interleaving question: two 'message' events, list then ping. List event: sync run → schedules microtasks. Ping event: can node deliver BOTH 'message' events in one macrotask turn? Events are emitted via process.nextTick-ish? In ws, 'message' is an EventEmitter emit — emitted synchronously per parsed frame within the 'data' handler. So: data chunk with both frames → parser emits message(list) → handler runs (sync to first await, schedules microtasks) → **returns to the data handler** → parser emits message(ping) → pong sent! → data handler returns → THEN microtasks drain → error frame sent.

EventEmitter emits are SYNCHRONOUS calls — the microtask queue does NOT drain between two emits in the same synchronous stack! Microtasks only run when the JS stack empties. THAT's the bug in my ordering assumption: both frames parsed in one 'data' callback → both handlers run back-to-back synchronously → pong written before the error frame.

Wait, but connectionHandler has `ws.pause()` and resumes — frames arrive as data events. If both frames land in one TCP segment (very likely — client sends them back-to-back), the above happens. Under load, packet timing varies — sometimes they arrive separately (error first ✓), sometimes together (pong first ✗). That's the flakiness — and it exists in the ORIGINAL test design too (the original askAfterConnect sends list+ping back-to-back). The original author's test at HEAD would have had the same race... but it never ran green because no handler existed. Hmm.

So how do the OTHER tests avoid this? Test 1 (the happy path with seen/frames) — the store's listFor returns a plain array synchronously — `await summaries` — microtask — same race: session_list vs pong. It passed consistently so far... but could flake the same way! Hmm, and in CI's earlier runs, test 1 failed only because no handler existed.

Hold on — wait. Let me re-check: microtasks DON'T drain between synchronous emits. So in EVERY case where list+ping arrive in one data chunk, pong precedes the answer frame. Test 1 passed in my runs — meaning list and ping usually arrive in separate chunks locally... The client sends two `client.send()` calls back-to-back; ws client may write them as two writes → two TCP segments → server two data events → microtasks drain between → answer first ✓. Nagle/coalescing varies by timing → flaky.

Hmm wait, but hold on — actually, is that really true for ws server parsing? Let me check `parseWsData` and connectionHandler: `ws.on('message', frame => {...})` — the 'message' event comes from the ws library per frame. When one data chunk contains two frames, ws's receiver emits 'message' twice within the same data handler synchronously. Yes — synchronous emits.

So how do OTHER suites in this repo handle this? sessionResume's connectAndSettle: pushes EVERY frame, resolves on pong — ordering doesn't matter there because it collects everything and only uses pong as a barrier. Its comment: "A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote." — that assumption relies on replay frames being written BEFORE the pong... and replay (replayEntries) is synchronous sends in the connection handler — so ordering holds there because both replay and pong are... hmm, pong is sent by the client's ping arriving later; replay is triggered by 'connection'. In any case, replay writes happen when the client sends ping only after connected — so replay is already written.

For MY case: the answer to list is asynchronous (microtask), the pong synchronous — ordering not guaranteed when both frames arrive in one chunk.

Fix options:
A. **In the test**: send the ping only after the answer frame arrives. E.g. in askAfterConnect: on connected → send outbound; on receiving a frame that is neither connected nor pong → push, THEN send ping (barrier). That makes the test deterministic: the pong is requested only after the answer was received. The test then waits for the answer with no timeout risk... and if the answer never comes, the test hangs — no: `eventually`-style timeouts? Hanging is bad. But this is exactly sessionResume's barrier pattern: send ping AFTER the frame you're waiting for arrives. Actually cleaner: on connected → send outbound; on each subsequent frame: if it's the answer to outbound (or any non-pong frame), push and THEN send ping once; pong → resolve. 

B. **In the server**: make handlePing... no — the server's ordering is actually FINE semantically ("answered off the lock, at once"); the ping is not ordered relative to other answers by contract. The pong being fast is correct behavior. The acceptance criterion "answered before that turn's stream_end" is about the lock, not the ping.

So fix the test helper: use the ping as a barrier AFTER the answer arrives. Rewrite askAfterConnect:

```ts
const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
      // Asked only here, so the pong chases the answer and this read is a barrier, not a race.
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {connected, frames};
};
```
Hmm — prefer-early-return check: If1 (connected): consequent 2 statements, tail = 3 → wrapped(2) < 4 → safe ✓. If2 (pong): consequent 2, tail 2 → safe ✓. Flat statements at end ✓.

But careful — test 3 sends 8 bad frames + 1 bare, each on a NEW connection (askAfterConnect per frame) ✓ so per connection exactly one outbound; the answer arrives → push → ping → pong → resolve ✓ deterministic. If the answer NEVER arrives, the test hangs until jest timeout (5s default per test) — acceptable, it'd be a real failure.

Edge: could the server send extra frames (e.g. replay)? No resume here.

Edge: in test 2, `unimplemented`/`failed` — each gets its answer → ping → pong ✓.

Now, does this change what the test VERIFIES? The criterion "answered before that turn's stream_end — it does not wait on the lock" is a DIFFERENT acceptance bullet (a separate test, not yet on the branch). The barrier doesn't weaken anything: the test still asserts the exact frames.

Hmm — but wait. There's another wrinkle: is it possible the client receives the pong BEFORE the answer even with the barrier? Barrier: answer frame arrives → push → send ping → server answers pong. Client resolves on pong. The answer was already pushed ✓. Deterministic ✓.

One more consideration — the `message` listener stays attached after resolve; harmless.

But hmm, hold on — with the barrier, the client sends ping ONLY after receiving the answer. For the INVALID_MESSAGE frames: error frame arrives → push → ping → pong ✓.

Alright — but I realize I should double-check my ordering claim (synchronous emits within one data chunk) since the whole fix depends on it. Evidence: the flakiness itself. Local single-suite runs pass, parallel runs fail — packet coalescing variance. The barrier removes the race entirely. Also note: CI earlier (red build) had test failures at this exact test with `+ Received +3` — consistent with empty frames arrays.

Also — should I make the SERVER order deterministic instead (defensive)? No — the wire ordering between an async answer and an unrelated ping is not a contract; the client test defines its own barrier. The sessionResume suite uses exactly this barrier pattern (comment on line 127: "A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote").

Hmm, actually wait — one more thought. Is it MORE faithful to the protocol spec to keep ping-as-barrier semantics as the original test intended ("its pong can only follow every frame the answer wrote")? The original test comment says: "Real upgrades over a real socket: what the list_sessions frame answers is the contract". The barrier pattern preserves the intent.

Let me apply the askAfterConnect fix.

