1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {ExtWebSocket} from './connectionHandler.js';
7	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
8	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
9	import {validateMessage} from './validation.js';
10	import type {ValidationResult} from './validation.js';
11	import {PerSessionLock} from '../../shared/perSessionLock.js';
12	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
13	import {AIError} from '../../types/ai.js';
14	import type {MessageChunk} from '../../types/ai.js';
15	import {
16	  createUserEntry,
17	  createAssistantEntry,
18	  createThinkingEntry,
19	  createToolEntry,
20	} from '../../orchestration/entryFactories.js';
21	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
22	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
23	import {log} from '../../shared/logger.js';
24	
25	interface StreamState {
26	  thinkingIndex: number | null;
27	  assistantIndex: number | null;
28	  suppressOutput: boolean;
29	  sentAssistantIndices: number[];
30	}
31	
32	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
33	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
34	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore: SessionStore) {
35	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
36	  const lock = new PerSessionLock();
37	  return function handleMessage(
38	    ws: WebSocket,
39	    session: ChatSession,
40	    rawMessage: unknown,
41	    signal?: AbortSignal
42	  ): Promise<void> {
43	    const validation = validateMessage(rawMessage);
44	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
45	    if (isUserMessageFrame(rawMessage)) {
46	      return lock.run(session.sessionId, () =>
47	        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
48	      );
49	    }
50	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
51	    return wsErrorHandler(ws, async () => answerFrame(ws, sessionStore, validation));
52	  };
53	}
54	
55	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
56	async function answerInTurn(
57	  ws: WebSocket,
58	  session: ChatSession,
59	  orchestrator: ChatOrchestrator,
60	  sessionStore: SessionStore,
61	  validation: ValidationResult,
62	  signal: AbortSignal | undefined
63	): Promise<void> {
64	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
65	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
66	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
67	    return;
68	  }
69	  const startedAt = Date.now();
70	  try {
71	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
72	  } finally {
73	    endTurn(ws, session, signal, startedAt);
74	  }
75	}
76	
77	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
78	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
79	  if (signal?.aborted) {
80	    log.info('message', 'turn abandoned: its socket closed', {
81	      sessionId: session.sessionId,
82	      elapsedMs: Date.now() - startedAt,
83	    });
84	    return;
85	  }
86	  sendStreamEnd(ws);
87	}
88	
89	async function answerUserMessage(
90	  ws: WebSocket,
91	  session: ChatSession,
92	  orchestrator: ChatOrchestrator,
93	  sessionStore: SessionStore,
94	  validation: ValidationResult,
95	  signal: AbortSignal | undefined
96	): Promise<void> {
97	  const message = validation.valid ? validation.data : undefined;
98	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
99	  await answerFrame(ws, sessionStore, validation);
100	}
101	
102	// Everything but a turn is answered at once, off the per-session lock: a list mutates nothing and must not queue behind a stream.
103	async function answerFrame(ws: WebSocket, sessionStore: SessionStore, validation: ValidationResult): Promise<void> {
